    trendJackerDesc2: 'ให้หมวดหมู่หนึ่งของคุณขึ้นมาที่ตำแหน่งแรกในรายการแนวโน้ม เปิดใช้งานที่ระดับ Giant Tortoise (เต่าใหญ่) ปัจจุบันเปิดใช้งานแล้ว',
