    communitiesTitle: 'ชุมชนและกิจกรรม',
    communitiesDesc: 'ชุมชนเป็นพื้นที่ที่ดำเนินการโดยสมาชิกภายใน DeHub แต่ละคนมีฟีดรายชื่อสมาชิกสตรีมกิจกรรมและช่องทางการแจ้งเตือนของตัวเองทำให้ครีเอเตอร์และโปรเจกต์มีบ้านเฉพาะสำหรับผู้ชมโดยไม่ต้องออกจากแพลตฟอร์มชุมชนเป็นที่อยู่อาศัยของการมีส่วนร่วมที่เกิดขึ้นประจำ: สมาชิกโพสต์พูดคุยทำโพลและให้ทิปกันและพื้นผิวกิจกรรมที่ยังไม่ได้อ่านเป็นตราบนการนำทางด้านล่างเพื่อไม่ให้ใครพลาดสิ่งที่เกิดขึ้น',
    communitiesDesc2: 'กิจกรรมขยายชุมชนด้วยโปรแกรมที่มีเวลาจำกัดชุมชนหรือแพลตฟอร์มสามารถกำหนดเวลาจัดกิจกรรมเผยแพร่หน้ากิจกรรมโดยเฉพาะพร้อมรายละเอียดทั้งหมดและให้สมาชิกติดตามไลฟ์สดได้เมื่อเริ่มจัดกิจกรรมชุมชนและกิจกรรมร่วมกันทำให้ระบบนิเวศมีเครื่องมือในการจัดระเบียบเกี่ยวกับความสนใจร่วมกันและทำให้ผู้คนกลับมาอีกครั้ง',
    communitiesB1: 'เรียกดูและเข้าร่วม:',
