    communitiesB3: 'กิจกรรม:',
    communitiesB3Desc: 'เรียกดูแพลตฟอร์มและกิจกรรมชุมชนเปิดหน้ากิจกรรมเพื่อดูวาระการประชุมและรายละเอียดทั้งหมดและติดตามการถ่ายทอดสดเมื่อกิจกรรมเริ่มขึ้น',
    stagesTitle: 'ขั้นตอน: ห้องเสียงสด',
