    stagesDesc2: 'สิ่งที่ทำให้ DeHub แตกต่างคือชั้นการผลิตเจ้าของที่พักจะได้รับซาวด์บอร์ดสไตล์ดีเจที่ผสมซาวด์เอฟเฟ็กต์คลิปเพลงของตัวเองและสถานีวิทยุสดเข้ากับเสียงในห้องที่เผยแพร่รวมถึงเอฟเฟ็กต์เสียงเพื่อให้เวทีรู้สึกเหมือนเป็นรายการที่ผลิตมากกว่าการประชุมทางโทรศัพท์เจ้าของที่พักแชร์หน้าจอเรียกใช้ทั้งหมดได้จากเบราว์เซอร์โดยไม่ต้องใช้ OBS หรือคีย์สตรีมและกำหนดเวลาจองห้องล่วงหน้าเพื่อให้ผู้เข้าพักรอก่อนที่ประตูจะเปิด',
    stagesDesc3: 'ห้องอ่านง่ายเช่นกันคำบรรยายสดผู้พูดทุกคนขณะที่พวกเขาพูดและได้รับการแปลเป็นภาษาใดก็ตามที่ผู้ฟังแต่ละคนกำลังอ่านอยู่เพื่อให้สามารถติดตามเวทีในภาษาที่ไม่มีใครบนเวทีพูดการพากย์สดก้าวไปอีกขั้นและพูดเสียงห้องดังๆด้วยเสียงโคลนของเจ้าของที่พักเองเรียกเก็บเงินเป็นนาทีด้วยโทเค็น DeHub ลิ้นชักบันทึกเสียงแบบสดและข้อความต่อคำช่วยให้ห้องใช้งานได้โดยไม่ต้องใช้ไมโครโฟนและมินิเพลเยอร์แบบต่อเนื่องช่วยให้คุณสามารถเรียกดูส่วนที่เหลือของแอปในขณะที่เล่นบนเวทีได้',
    stagesB1: 'โฮสต์และพูด:',
