    stagesB4: 'การบันทึก:',
    stagesB4Desc: 'บันทึกขั้นตอนและบันทึกย้อนกลับจากการ์ดที่ปรากฏ — สามารถค้นหาได้ด้วยความเร็วที่คุณเลือกคมชัดและสามารถโพสต์ได้โดยตรงจากแผ่นแชร์ผู้เล่นมุมที่ใช้ร่วมกันจะพามันไปทั่วเว็บและมือถือ',
    stagesB5: 'กำหนดเวลาและแจ้งเตือน:',
    stagesB5Desc: 'ประกาศเวทีล่วงหน้าพร้อมลิงก์คำเชิญสั้นๆและบัตรแชร์ของตัวเองทุกคนที่ตั้งค่าการแจ้งเตือนจะได้รับการแจ้งเตือนเมื่อมันกำลังจะเริ่มและอีกครั้งเมื่อมันเริ่มทำงาน',
    stagesB6: 'คำบรรยายและคำแปล:',
