    affiliateB3: 'ติดตามทุกอย่าง:',
    affiliateB3Desc: 'แดชบอร์ด Affiliate จะแสดงการคลิกการลงทะเบียนและรายได้ของคุณเพื่อให้คุณสามารถเห็นได้อย่างชัดเจนว่าผู้ได้รับการแนะนำของคุณสร้างอะไรได้บ้าง',
    aiSuiteDesc: 'DeHub รวมชุดเครื่องมือ AI เต็มรูปแบบสำหรับครีเอเตอร์ทั้งหมดนี้มีอยู่ในแอปโดยไม่มีบัญชีภายนอกหรือคีย์ API สวีทครอบคลุมผู้ช่วยการสนทนาตัวแทนอัตโนมัติและเครื่องมือสร้างแอปที่ไม่มีรหัสเพื่อให้คุณสามารถเปลี่ยนจากไอเดียไปเป็นเนื้อหาที่สร้างขึ้นหรือแอปขนาดเล็กที่ทำงานได้โดยไม่ต้องออกจากแพลตฟอร์ม',
    aiSuiteB1: 'ผู้ช่วย AI:',
    aiSuiteB1Desc: 'ผู้ช่วยแชทที่ตอบคำถามเกี่ยวกับ DeHub สร้างโปสเตอร์และเนื้อหาการตลาดและช่วยคุณวางแผนและสร้างเนื้อหา',
    aiSuiteB2: 'ตัวแทน AI:',
