    aiSuiteB3Desc: 'อธิบายแอปเป็นภาษาธรรมดาและ Builder จะสร้างแอปจากนั้นให้ลิงก์ตัวอย่างแบบไลฟ์สดที่แชร์ได้เพื่อส่งให้ทุกคนอยู่ที่ dehub.io/builder',
    aiSuiteB4: 'ครีเอเตอร์สตูดิโอ:',
    aiSuiteB4Desc: 'สตูดิโอรุ่นเนทีฟสำหรับภาพวิดีโอเสียงเพลงและโมเดล 3 มิติที่มีตัวแก้ไขสไตล์ Canva อยู่ด้านบนคิวการแสดงผลที่ใช้ร่วมกันซึ่งยังคงทำงานต่อไปในขณะที่คุณท่องเว็บและไลบรารีสินทรัพย์หุ้นฟรีที่จะดึงออกมา',
    aiSuiteB5Desc: 'พูดถึง @ assistant ในโพสต์ในชุดความคิดเห็นหรือในแชทสดและตอบคำถามโดยใช้เครื่องมือแพลตฟอร์มจริงมากกว่าการจับคู่คำหลักนอกจากนี้ยังสามารถยื่นตั๋วสนับสนุนที่เข้าถึงมนุษย์ได้อีกด้วย',
    aiSuiteCreditsTitle: 'วิธีการชำระเงินสำหรับการสร้าง',
    aiSuiteCreditsDesc: 'เจเนอเรชั่นทำงานบนเครดิต AI ซึ่งแสดงในโทเค็น DeHub แทนที่จะเป็นสกุลเงินแยกที่คุณต้องซื้อทุกบัญชีจะได้รับเงินช่วยเหลือเริ่มต้นและสะสมเพิ่มขึ้นในแต่ละวันดังนั้นจึงมีเครดิตฟรีให้เข้าถึงอยู่เสมอและเซิร์ฟเวอร์จะเสนอราคาของงานก่อนที่จะทำงาน — คุณจะเห็นค่าใช้จ่ายก่อนที่จะใช้จ่ายอะไรก็ตามที่นอกเหนือจากเงินสะสมฟรีจะออกมาจากยอดคงเหลือโทเค็นของคุณในอัตราเดียวกันการพากย์สเตจจะถูกเรียกเก็บเงินในลักษณะเดียวกันในหนึ่งนาที',
    aiSuiteLink: 'อ่านเอกสารชุดเครื่องมือ AI ฉบับเต็ม',
