    adsPortalLink: 'อ่านเอกสารประกอบการโฆษณาฉบับเต็ม',
    featureBoardTitle: 'คำขอฟีเจอร์',
    featureBoardDesc: 'DeHub สร้างขึ้นพร้อมกับชุมชนส่งไอเดียในกระดานคำขอฟีเจอร์โหวตคำขอของผู้อื่นและดูว่าพวกเขาย้ายไปยังการจัดส่งหรือไม่หากฟีเจอร์ที่คุณขอใช้งานได้จริงแอพจะแจ้งให้คุณทราบด้วยการแจ้งเตือนส่วนบุคคล',
    connectTitle: 'เชื่อมต่อ AI (MCP)',
    connectDesc: 'เชื่อมโยง DeHub กับ ChatGPT หรือ Claude ผ่าน MCP และใช้ AI ที่คุณชื่นชอบเพื่อเรียกดูโพสต์และโต้ตอบกับแพลตฟอร์มในนามของคุณตั้งค่าได้ที่ dehub.io/connect',
    notificationsTitle: 'การแจ้งเตือน',
    notificationsDesc: 'ทุกอย่างที่เกิดขึ้นกับคุณลงจอดในศูนย์การแจ้งเตือนเดียวโดยแบ่งออกเป็นแท็บเพื่อให้การตอบกลับไม่ฝังการชำระเงินความคิดเห็นและการตอบกลับปฏิกิริยาบนโพสต์ของคุณผู้ติดตามรายใหม่เคล็ดลับและการซื้อการแจ้งเตือนบนเวทีและช่วงเวลาที่คุณจองเริ่มใช้งานกิจกรรมชุมชนและการแจ้งเตือนเมื่อฟีเจอร์ที่คุณขอบนกระดานคำขอจัดส่งจริง — ทั้งหมดอยู่ในที่เดียวกันพร้อมภาพขนาดย่อของการแจ้งเตือนเพื่อให้คุณสามารถแยกความแตกต่างได้อย่างรวดเร็ว',
    notificationsB1: 'เลือกสิ่งที่จะมาถึงคุณ:',
    notificationsB1Desc: 'การตั้งค่าตามหมวดหมู่ในการตั้งค่าจะเป็นตัวกำหนดว่าจะให้ส่งอะไรบ้างเพื่อให้คุณเก็บเคล็ดลับและลดการตอบสนองได้',
    notificationsB2: 'ผลักดันบนเว็บและมือถือ:',
    notificationsB2Desc: 'ทั้งสองแอปจะส่งพุชไปยังอุปกรณ์เอง — เบราว์เซอร์จะขออนุญาตหนึ่งครั้งแอป Android จะขอเมื่อติดตั้ง — และทุกอย่างจะลงจอดในศูนย์การแจ้งเตือนไม่ทางใดก็ทางหนึ่ง',
    notificationsB3: 'ประกาศ:',
