    notificationsB5Desc: 'ข้อความตัวอักษรเป็นช่องทางชำระเงินปลดล็อคเพียงครั้งเดียวยืนยันหมายเลขรักษายอดเงินเล็กน้อยและเลือกว่าทุกการแจ้งเตือนที่คุณเปิดไว้จะส่งข้อความถึงคุณหรือเฉพาะการแจ้งเตือนที่เกี่ยวข้องกับเงินเท่านั้นสวิตช์มีราคาของข้อความและสิ่งที่เหลืออยู่ในยอดคงเหลือเพราะการสลับที่เริ่มใช้จ่ายอย่างเงียบๆเป็นสิ่งเดียวที่จะต้องไม่เป็นเช่นนั้น',
    themesTitle: 'ธีมและรูปลักษณ์',
