    daoTitle: 'มีส่วนร่วมผ่าน DAO',
    daoBody: 'ที่อยู่ EVM ด้านบนคือคลัง DAO ส่งโทเค็น DeHub ไปที่โทเค็นนั้นจากแอปและการมีส่วนร่วมของคุณจะถูกนับรวมในส่วนแบ่งของพูลซึ่งเป็นน้ำหนักที่คะแนนโหวตของคุณมีเมื่อ DAO ตัดสินใจว่าจะใช้จ่ายอย่างไร',
