    pegDesc2: 'โทเค็นซื้อขายในการแลกเปลี่ยนแบบกระจายอำนาจโดยมีกลุ่มสภาพคล่องที่มีเมล็ดจากราคาพื้นฐาน 0.001 เท่ากันในหลายโซ่ในตลาดเปิดราคาถูกกำหนดโดยการเทรด — ไม่ใช่โดย DeHub - ซึ่งหมายความว่าโทเค็น DeHub สามารถเทรดสูงหรือต่ำกว่า PEG ในแอปได้ตลอดเวลา DeHub มีสภาพคล่องอย่างเป็นทางการใน DEXs เพื่อให้ธุรกรรมทุกรายการสามารถตรวจสอบได้แบบสาธารณะในห่วงโซ่',
    disclaimer: 'ข้อจำกัดความรับผิดชอบ',
    disclaimerNoApy: 'สำคัญ: ในขณะที่ถือโทเค็น DeHub ให้ความเป็นเจ้าของในเครือข่าย DeHub และมีสิทธิ์ได้รับส่วนแบ่งกำไรจากโปรโตคอลแต่ไม่มีการกำหนด APY ไม่มีอัตราผลตอบแทนที่รับประกันและไม่คาดหวังผลกำไรใดๆการกระจายทั้งหมดขึ้นอยู่กับประสิทธิภาพของเครือข่ายและรายได้ที่โปรโตคอลสร้างขึ้นจริงในช่วงเวลาที่กำหนดรางวัลอาจต่ำกว่าช่วงเวลาก่อนหน้านี้และอาจเป็นศูนย์ ไม่มีอะไรในหน้านี้ที่เป็นสัญญาการคาดการณ์หรือข้อเสนอของผลตอบแทนและไม่มีอะไรที่นี่เป็นคำแนะนำทางการเงิน',
    disclaimerText: 'โทเค็น DeHub มีวัตถุประสงค์เพื่อประโยชน์ใช้สอยอย่างเคร่งครัดในลักษณะเดียวกับโทเค็นหรือสกุลเงินดิจิทัลในเกมหรือในแอปและไม่ใช่การลงทุนอย่างเคร่งครัดเนื่องจากโทเค็นของเราอยู่ในห่วงโซ่เราจึงสามารถนำเสนออรรถประโยชน์เพิ่มเติมรวมถึงความโปร่งใสที่ตรวจสอบได้ในระดับที่ไม่เคยมีมาก่อนข้อมูลข้างต้นรวบรวมขึ้นเพื่อวัตถุประสงค์ด้านความโปร่งใสการศึกษาและการให้ข้อมูลเท่านั้น DeHub และบริษัทในเครือทั้งหมดจะไม่รับผิดชอบต่อความสูญเสียทางการเงินที่เกิดขึ้นจากการซื้อโทเค็นหรือ NFT ที่เราปล่อยออกมาตลาดมีความผันผวนสูงนอกจากนี้คุณยังอาจสูญเสียเงินทั้งหมดของคุณเนื่องจากข้อผิดพลาดที่ไม่คาดคิดเช่นความล้มเหลวด้านความสามารถข้อผิดพลาดทางเทคนิคการแฮ็กและอื่นๆดังนั้นคุณควรใช้จ่ายในสิ่งที่คุณสามารถสูญเสียได้เท่านั้น',
